import{_ as s,c as t,o as l,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易集說","description":"周易集說 - 周易集說","frontmatter":{"title":"周易集說","description":"周易集說 - 周易集說"},"headers":[],"relativePath":"classics/jishuo/001.md","filePath":"classics/jishuo/001.md"}'),n={name:"classics/jishuo/001.md"};function o(i,a,c,p,d,u){return l(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易集說",tabindex:"-1"},[r("周易集說 "),e("a",{class:"header-anchor",href:"#周易集說","aria-label":"Permalink to “周易集說”"},"​")],-1),e("p",null,"欽定四庫全書經部一",-1),e("p",null,"易類提要",-1),e("p",null,"臣 等謹案：周易集說四十卷，宋俞琰撰。琰字玉吾，吳人。讀易三十餘年，未嘗倦輟。其書集諸家之說，用功閱二十八年，凡四易稿始成。同時漢東孟淳、單父李克寬、錢唐白珽、西秦張瑛、同郡顏堯煥、幹文傳諸輩，皆推而重之。琰嘗與孟淳講坤之六二，謂六二既中且正，是以其德直方，惟從乾陽之大，不習坤陰之小，故無不利。又謂彖傳「剛柔上下」，言來不言往，皆以兩卦相併而取義。其發諸儒所未發，多類於此。琰又有讀易須知、易圖纂要、易經考證、易傳考證、六十四卦圖、古佔法、卦爻象佔分類、易圖合璧連珠、易外傳諸書，今皆不傳。然其自為後序稱諸編皆舊所作，將毀之，而兒輩以為可惜，又略加改竄，而存於後。則舊刻本附此數書，今佚之也。乾隆四十六年十月恭校上。",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。周易集說序：",-1),e("p",null,"周易集說者，集諸說之善而為之說也。曷為善？能明三聖人之本旨則善也。夫易始作於伏羲，僅有六十四卦之畫，而未有辭。文王作上下經，乃始有辭。孔子作十翼，其辭乃備。當知辭本於象，象本於畫，有畫斯有象，有象斯有辭。易之理盡在於畫，詎可舍六畫之象，而專論辭之理哉！舍畫而玩辭，舍象而窮理，辭雖明，理雖通，非易也。漢去古未遠，諸儒訓解多論象數，蓋亦有所本。至魏王弼以老莊之虛無倡於前，普、韓康伯又和於後，聖人之本旨遂晦。沿襲至於唐，諸儒皆宗之。太宗詔名儒定九經正義，於易則取王、韓，而孔穎達輩以當時所尚，故雖其說未盡善，亦必為之迴護。由是二三百年間，皆以虛無為高。至宋，濂、洛諸公彬彬輩出，一埽虛無之弊，聖人之本旨始明。奈何世之尚佔而宗邵康節者，則以義理為虛文；尚辭而宗程伊川者，則以象數為末技。而邵、程之學分為兩家，羲畫、周經亦為兩途，遂使學者莫之適從。逮夫紫陽朱子本義之作，發邵、程之未發，辭必本於畫，理不外於象，聖人之本旨於是乎大明焉。琰幼承父師面命，首讀朱子本義，次讀程傳，長與朋友講明，則又有程、朱二公所未言者，於心蓋不能無疑。乃歷考諸家易說，摭其英華，萃為一書，名曰大易會要，凡一百三十卷。不揣固陋，遂自至元甲申集諸說之善而為之說，凡四十卷，因名之曰周易集說雲。元貞丙申五月六日，林屋山人俞琰序。",-1)])])}const f=s(n,[["render",o]]);export{_ as __pageData,f as default};
